package main

import (
	"fmt"
	"os"
	"strconv"
	"strings"
)

type PartRec struct { // 01 PART-REC, 15 bytes
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

var WsEofFlag string = "N"                           // PIC X len=1 = "N"
var WsLabel string = "                    "           // PIC X(20) len=20 = SPACES (20 spaces)
var WsACount int64 = 0                               // PIC 99 len=2 = 0
var WsTotalA int64 = 0                               // PIC 999 len=3 = 0
var WsCount int64 = 0                                // PIC 999 len=3 = 0

var inputRecords []string
var curIdx int
var PartRecData PartRec

func main() {
	MAIN_PARA()
}

func MAIN_PARA() {
	loadInput()
	curIdx = 0
	READ_PARA()
	for WsEofFlag != "Y" {
		PROCESS_PARA()
	}
	SUMMARY_PARA()
}

func READ_PARA() {
	if curIdx >= len(inputRecords) {
		WsEofFlag = "Y"
		return
	}
	line := inputRecords[curIdx]
	curIdx++
	recStr := line
	if len(recStr) < 15 {
		recStr = recStr + strings.Repeat(" ", 15-len(recStr))
	} else if len(recStr) > 15 {
		recStr = recStr[:15]
	}
	PartRecData.LbPart = recStr[0:8]
	PartRecData.LbRegion = recStr[8:11]
	serialStr := recStr[11:15]
	trimmed := strings.TrimSpace(serialStr)
	var val int64 = 0
	if trimmed != "" {
		if v, err := strconv.ParseInt(trimmed, 10, 64); err == nil {
			val = v
		} else {
			var acc int64
			for _, ch := range serialStr {
				if ch >= '0' && ch <= '9' {
					acc = acc*10 + int64(ch-'0')
				}
			}
			val = acc
		}
	}
	PartRecData.LbSerial = val % 10000
	WsEofFlag = "N"
}

func PROCESS_PARA() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	cnt := strings.Count(PartRecData.LbPart, "A")
	WsACount = int64(cnt) % 100

	regionPart := delimitedBySpace(PartRecData.LbRegion)
	partPart := delimitedBySpace(PartRecData.LbPart)
	serialPart := fmt.Sprintf("%04d", PartRecData.LbSerial)
	concatenated := regionPart + "-" + partPart + "-" + serialPart
	if len(concatenated) > 20 {
		concatenated = concatenated[:20]
	}
	WsLabel = concatenated + strings.Repeat(" ", 20-len(concatenated))
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")

	WsTotalA = (WsTotalA + WsACount) % 1000
	WsCount = (WsCount + 1) % 1000

	wsACountStr := fmt.Sprintf("%02d", WsACount)
	outLine := WsLabel + " A=" + wsACountStr
	fmt.Fprint(os.Stdout, outLine+"\n")

	READ_PARA()
}

func SUMMARY_PARA() {
	wsCountStr := fmt.Sprintf("%03d", WsCount)
	wsTotalAStr := fmt.Sprintf("%03d", WsTotalA)
	outLine := "LABELS: " + wsCountStr + " A-TOTAL: " + wsTotalAStr
	fmt.Fprint(os.Stdout, outLine+"\n")
}

func delimitedBySpace(s string) string {
	if idx := strings.Index(s, " "); idx != -1 {
		return s[:idx]
	}
	return s
}

func loadInput() {
	data, err := os.ReadFile("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "failed to open input.dat: %v\n", err)
		os.Exit(1)
	}
	content := string(data)
	content = strings.ReplaceAll(content, "\r\n", "\n")
	content = strings.ReplaceAll(content, "\r", "\n")
	if content == "" {
		inputRecords = []string{}
		return
	}
	parts := strings.Split(content, "\n")
	if strings.HasSuffix(content, "\n") {
		if len(parts) > 0 && parts[len(parts)-1] == "" {
			parts = parts[:len(parts)-1]
		}
	}
	inputRecords = parts
}
